const item = $input.first().json;
const text = String(item.message || item.raw_llm_output || '');
let parsed = null;
try {
  const match = text.match(/\{[\s\S]*\}/);
  if (match) parsed = JSON.parse(match[0]);
} catch (e) { parsed = null; }
const allowedTiers = ['HOT', 'WARM', 'COLD'];
if (parsed && allowedTiers.includes(parsed.tier) && typeof parsed.summary === 'string') {
  return [{ json: { ...item, tier: parsed.tier, summary: parsed.summary, fallback_used: false } }];
}
const tier = /(urgent|budget|rfq|pilot|quote|enterprise)/i.test(text) ? 'HOT' : 'WARM';
return [{ json: { ...item, tier, summary: text.slice(0, 240), fallback_used: true, fallback_reason: 'LLM schema validation failed; deterministic rule applied' } }];
